/* eslint-disable @typescript-eslint/no-explicit-any */
// Per-client mock trees — fe/client/<name>/mock/<lang>/<endpoint>/<METHOD>/<response>.json
// plus the per-client registry fe/client/<name>/mock/config.json
// ({endpoint: {METHOD: {mock, response_type, status, delay, id, search_param}}}).
//
// The file list comes from src/tenants/mock-active.ts (generated by
// `npm run client <name>`): a literal glob that bundles ONLY the active
// client's mock tree. A client with no mock/ folder gets an empty map and
// every call falls through to the real API — the ApiResponse contract
// never changes.
import type { ApiConfigMap } from "./api";
import { mockFiles as files } from "../../tenants/mock-active";

const fileMap = files as Record<string, any>;

type ResponseFiles = Record<string, any>;
type EndpointMap = Record<string, ResponseFiles>; // METHOD -> file -> json
type LangMap = Record<string, EndpointMap>;       // endpoint -> EndpointMap

// mockData[lang][endpoint][METHOD][responseType] = json
export const mockData: LangMap = {};

// The active client's endpoint registry (mock/config.json)
export let mockConfig: ApiConfigMap = {};

for (const path in fileMap) {
  // path: ../../../client/<name>/mock/<...>
  const rel = path.split("/mock/")[1];
  if (!rel) continue;
  const parts = rel.split("/").filter(Boolean);
  const json = fileMap[path]?.default ?? fileMap[path];

  if (parts.length === 1 && parts[0] === "config.json") {
    mockConfig = json;
    continue;
  }

  // [lang, ...endpoint, METHOD, file.json]
  if (parts.length < 4) continue;
  const lang = parts[0];
  const file = parts[parts.length - 1].replace(/\.json$/, "");
  const method = parts[parts.length - 2];
  const endpoint = parts.slice(1, -2).join("/");

  (mockData[lang] ??= {})[endpoint] ??= {};
  mockData[lang][endpoint][method] ??= {};
  mockData[lang][endpoint][method][file] = json;
}
